* { box-sizing: border-box; }
html, body { margin: 0; padding: 0; }
.wm-wrap { height: calc(var(--appsmith-ui-height) * 1px); width: calc(var(--appsmith-ui-width) * 1px); background:#fff; border:1px solid #e2e8f0; border-radius:6px; overflow:hidden; font-family:system-ui; display:flex; flex-direction:column; }
.wm-title { padding:8px 14px; font-size:13px; font-weight:600; color:#0f172a; border-bottom:1px solid #e2e8f0; flex:0 0 auto; }
.wm-empty { flex:1 1 auto; display:flex; align-items:center; justify-content:center; color:#94a3b8; font-size:13px; }
#map { flex:1 1 auto; width:100%; min-height:120px; }

