var map, layer;
function waitForL(cb, tries){
  tries = tries || 0;
  if (window.L) { cb(); }
  else if (tries < 100) { setTimeout(function(){ waitForL(cb, tries + 1); }, 80); }
}
function fmt(n){ return Math.round(Number(n) || 0).toLocaleString(); }
function render(model){
  var markers = (model && model.markers) || [];
  waitForL(function(){
    if (!map) {
      map = L.map('map', { attributionControl: false, zoomControl: true }).setView([39.8283, -98.5795], 4);
      L.tileLayer('https://{s}.basemaps.cartocdn.com/light_all/{z}/{x}/{y}{r}.png', { maxZoom: 19 }).addTo(map);
      layer = L.layerGroup().addTo(map);
    }
    layer.clearLayers();
    var max = 0;
    markers.forEach(function(m){ if ((m.maxBill || 0) > max) max = m.maxBill; });
    var bounds = [];
    markers.forEach(function(m){
      if (m.lat == null || m.lng == null || isNaN(m.lat) || isNaN(m.lng)) return;
      var r = max > 0 ? (6 + 24 * Math.sqrt((m.maxBill || 0) / max)) : 8;
      var c = L.circleMarker([m.lat, m.lng], { radius: r, color: '#1d4ed8', weight: 1, fillColor: '#3b82f6', fillOpacity: 0.45 });
      c.bindTooltip((m.location || '') + ': $' + fmt(m.maxBill) + ' (' + (m.count || 0) + ' warnings)');
      c.addTo(layer);
      bounds.push([m.lat, m.lng]);
    });
    if (bounds.length) { map.fitBounds(bounds, { padding: [30, 30], maxZoom: 10 }); }
    setTimeout(function(){ map.invalidateSize(); }, 150);
  });
}
appsmith.onReady(function(){ render(appsmith.model); appsmith.onModelChange(function(m){ render(m); }); });

